/*
  Species reference list for the caterpillar checklist (checklist.md).

  Source: David Beadle and Alan Macnaughton, TEA Checklist of Ontario Moths
          (13 September 2026), plus butterflies.

  One species per line. Fields:
    sci     scientific name (required)
    common  common name (use "" if there isn't one)
    fam     family
    h       Hodges number; the exported table is sorted by this (use a decimal
            like 4363.1 to slot an entry between two numbers)

  To add a species, copy any line below, edit it, and save. Keep the trailing comma.
*/

